add_filter( 'woocommerce_default_address_fields', 'perfectpixel_house_number_field', 9999 );
add_filter( 'woocommerce_order_formatted_billing_address', 'perfectpixel_house_number_billing', 10, 2 );
add_filter( 'woocommerce_order_formatted_shipping_address', 'perfectpixel_house_number_shipping', 10, 2 );

function perfectpixel_house_number_field( $fields ) {
	if ( isset( $fields['address_1'] ) ) {
		$fields['address_1']['class'] = array( 'form-row-first' );
	}
	$fields['house_number'] = array(
		'label'    => '{{house_number_label}}',
		'required' => true,
		'class'    => array( 'form-row-last' ),
		'priority' => 55,
	);
	return $fields;
}

function perfectpixel_house_number_append( $address, $number ) {
	$number = trim( (string) $number );
	if ( is_array( $address ) && '' !== $number && isset( $address['address_1'] ) ) {
		$address['address_1'] = trim( $address['address_1'] . ' ' . $number );
	}
	return $address;
}

function perfectpixel_house_number_billing( $address, $order ) {
	return perfectpixel_house_number_append( $address, $order->get_meta( '_billing_house_number' ) );
}

function perfectpixel_house_number_shipping( $address, $order ) {
	return perfectpixel_house_number_append( $address, $order->get_meta( '_shipping_house_number' ) );
}
